import { DATA_FRAME_TYPES } from '../../../../../../data/public';

/**
 * if we should display index pattern creation in the sidebar
 */
export function displayIndexPatternCreation(indexPattern) {
  if (!indexPattern || !indexPattern.type || !indexPattern.id) return false;
  return Object.values(DATA_FRAME_TYPES).includes(indexPattern.type) && Object.values(DATA_FRAME_TYPES).includes(indexPattern.id);
}